service.method:

SELECT
	BIZ_CIDE
FROM
	SBUPR
WHERE
		HOUSE_CODE 			= ${HOUSE_CODE}
	AND COMPANY_CODE 		= ${COMPANY_CODE}	
	AND BIZ_CODE 			= ${BIZ_CODE}
	AND #DB_OWNER#nvl(DEL_FLAG, 'N') 	= 'N'


UPDATE SBUPR
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, SELLER_NAME_LOC = ${SELLER_NAME_LOC}
		, IRS_NO = ${IRS_NO}
		, PHONE_NO = ${PHONE_NO}
		, EMAIL = ${EMAIL}
		, CEO_NAME_LOC = ${CEO_NAME_LOC}
WHERE
	  HOUSE_CODE        	= ${HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND BIZ_CODE           	= ${BIZ_CODE}


INSERT INTO SBUPR
	(
		  HOUSE_CODE
		, BIZ_CODE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, DEL_FLAG
		, SELLER_NAME_LOC
		, IRS_NO
		, PHONE_NO
		, EMAIL
		, CEO_NAME_LOC
	)
	VALUES
	(
		  HOUSE_CODE = ${HOUSE_CODE}
		, BIZ_CODE = ${BIZ_CODE}
		, ADD_DATE = ${current.DATE}
		, ADD_TIME = ${current.TIME}
		, ADD_USER_ID = ${session.ID}
		, DEL_FLAG = 'N'
		, SELLER_NAME_LOC = ${SELLER_NAME_LOC}
		, IRS_NO = ${IRS_NO}
		, PHONE_NO = ${PHONE_NO}
		, EMAIL = ${EMAIL}
		, CEO_NAME_LOC = ${CEO_NAME_LOC}
	)


UPDATE SBUPR
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, DEL_FLAG			= 'Y'
WHERE
	  HOUSE_CODE        	= ${HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND BIZ_CODE           	= ${BIZ_CODE}


UPDATE BAT_UP_IMBUPR
   SET IF_FLAG  	= #{IF_RESULT}
 WHERE INS_TIME 	= #{INS_TIME}
   AND BIZ_CODE  	= #{BIZ_CODE}
